shimmer:
@keyframes shimmer { 
  0% { background-position: 0px center; }
  50% { background-position: 100% center; }
  100% { background-position: 0px center; }
}

selector-shimmer:
@keyframes selector-shimmer { 
  0%, 100% { opacity: 0; transform: translate(-100%); }
  50% { opacity: 1; transform: translate(100%); }
}

chevron-tap:
@keyframes chevron-tap { 
  0%, 100% { color: rgb(156, 163, 175); filter: brightness(); transform: translateY(0px) scale(1); }
  20% { color: rgb(244, 114, 182); filter: brightness(1.3) drop-shadow(rgb(244, 114, 182) 0px 0px 4px); transform: translateY(4px) scale(1.15); }
  30% { color: rgb(244, 114, 182); filter: brightness(1.2); transform: translateY(0px) scale(1); }
  40% { color: rgb(244, 114, 182); filter: brightness(1.3) drop-shadow(rgb(244, 114, 182) 0px 0px 4px); transform: translateY(4px) scale(1.15); }
  50% { color: rgb(156, 163, 175); filter: brightness(); transform: translateY(0px) scale(1); }
}

fadeIn:
@keyframes fadeIn { 
  0% { opacity: 0; transform: translateY(-10px); }
  100% { opacity: 1; transform: translateY(0px); }
}

modalSlideUp:
@keyframes modalSlideUp { 
  0% { opacity: 0; transform: translateY(100%); }
  100% { opacity: 1; transform: translateY(0px); }
}

modalScaleIn:
@keyframes modalScaleIn { 
  0% { opacity: 0; transform: scale(0.95); }
  100% { opacity: 1; transform: scale(1); }
}

staggerFadeIn:
@keyframes staggerFadeIn { 
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0px); }
}

bounce:
@keyframes bounce { 
  0%, 100% { animation-timing-function: cubic-bezier(0.8, 0, 1, 1); transform: translateY(-25%); }
  50% { animation-timing-function: cubic-bezier(0, 0, 0.2, 1); transform: none; }
}

pointerBounce:
@keyframes pointerBounce { 
  0%, 100% { transform: translateX(-50%) translateY(0px); }
  50% { transform: translateX(-50%) translateY(-8px); }
}

shake:
@keyframes shake { 
  0%, 100% { transform: translateX(0px); }
  20% { transform: translateX(-8px); }
  40% { transform: translateX(8px); }
  60% { transform: translateX(-6px); }
  80% { transform: translateX(6px); }
}
